"""Development-only literal data exporter; does not translate PHP algorithms."""
import json
import re
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent

def write(name, data):
    (ROOT / 'js/data' / (name + '.js')).write_text(
        '// Original Wizardawn literal tables. Generated by extract-tables.py.\n'
        'window.WZ_DATA = window.WZ_DATA || {};\nwindow.WZ_DATA.' + name + ' = ' + json.dumps(data, ensure_ascii=False) + ';\n')

def arrays(text):
    for m in re.finditer(r'\$(\w+)\s*=\s*array\(', text):
        start = m.end()
        i, depth, quote = start, 1, None
        while i < len(text) and depth:
            c = text[i]
            if c == '\\' and quote:
                i += 2
                continue
            if quote:
                if c == quote:
                    quote = None
            elif c in "'\"":
                quote = c
            elif c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            i += 1
        raw = text[start:i-1]
        tokens = re.findall(r"'(?:[^'\\]|\\.)*'|\"(?:[^\"\\]|\\.)*\"|[-+]?\d+(?:\.\d+)?", raw)
        rest = re.sub(r"'(?:[^'\\]|\\.)*'|\"(?:[^\"\\]|\\.)*\"|[-+]?\d+(?:\.\d+)?", '', raw)
        if rest.replace(',', '').strip() or not tokens:
            continue
        values = []
        for token in tokens:
            if token[0] in "'\"":
                v = token[1:-1].replace('\\' + token[0], token[0]).replace('\\\\', '\\')
                if token[0] == '"':
                    v = v.replace('\\n', '\n').replace('\\t', '\t').replace('\\r', '\r')
                    if '$' in v:
                        raise ValueError('Interpolated PHP is not literal data: ' + m[1])
                values.append(v)
            else:
                values.append(float(token) if '.' in token else int(token))
        yield m[1], values

def function_tables(file, names):
    text = (ROOT / 'src/functions' / (file + '.php')).read_text(encoding='cp1252')
    result = {}
    for part in re.split(r'(?m)^function\s+', text)[1:]:
        name = re.match(r'\w+', part)[0]
        if name in names:
            result[name] = {}
            for key, values in arrays(part):
                result[name].setdefault(key, []).append(values)
    return result

names = '''DarkElfParts holmesPart ConanFirst ConanLast ConanPlain demonName mageName jobName adjName classMaleName classFemaleName dragonName dwarfName gnomeName genericName humanMaleName humanFemaleName MaleName FemaleName wolfName goblinName catName orcName ratmanName lizardmanName impName elfName elfgirlName elfboyName authorName villageName tavernName'''.split()
write('names', function_tables('names', names))
write('books', function_tables('books', ['tomeMaker']))
write('spellNames', function_tables('spells', ['researchSpell']))
write('potionLooks', function_tables('potion_appearances', ['potionPretty']))
# One table per game/expansion, in the source's documented branch order.
write('brewPotions', [v for k, v in arrays((ROOT / 'src/tool_brew.php').read_text()) if k == 't_potions'])
for name in ['monsters_rpgs', 'lablord_spells', 'osric_spells']:
    source = json.loads((ROOT / 'data/json' / (name + '.json')).read_text())
    write(name, [dict(zip([c['name'] for c in source['columns']], row)) for row in source['rows']])

# Literal epithets for the Holmesian name table (editorial text, not code).
titles_text = (ROOT / 'src/functions/names.php').read_text().split('function holmesTitle')[1].split('function holmesName')[0]
titles = re.findall(r'\$title\s*=\s*"([^"$]*)"\s*;', titles_text)
write('holmesTitles', titles)
write('potionNames', [v for k, v in arrays((ROOT / 'src/tool_potions.php').read_text()) if k == 't_potions'])
write('reagents', function_tables('item_fantasy', ['contentsChooser']))
write('animals', function_tables('descriptions', ['animalPicker']))
# Fixed text rows in the last contentsChooser table.
reagent_text = (ROOT / 'src/functions/item_fantasy.php').read_text(encoding='cp1252').split('function contentsChooser')[1].split('function normalArmor')[0]
write('rareReagents', re.findall(r'case\s+\d+:\s*\$reagent\s*=\s*"([^"$]+)";', reagent_text))
animal_text = (ROOT / 'src/functions/descriptions.php').read_text(encoding='cp1252').split('function animalPicker')[1].split('function ')[0]
write('animals', re.findall(r'\$animal\s*=\s*"([^"$]+)";', animal_text))
# PickJunk is a literal seven-column table expressed as a PHP switch.
junk_text = (ROOT / 'src/functions/item_post_apocalyptic.php').read_text(encoding='cp1252').split('function PickJunk')[1]
junk = []
for line in junk_text.splitlines():
    if re.search(r'case\s+\d+:', line):
        pa = re.search(r'\$item_pa = "([^"]+)"', line)[1]
        sf = re.search(r'\$item_sf = "([^"]+)"', line)[1]
        values = [int(v) for v in re.findall(r'\$item_val\d = (\d+)', line)]
        assert len(values) == 5
        junk.append([pa, sf] + values)
assert len(junk) == 300
write('junk', junk)
# Classic geomorph metadata, decoded into named fields. Only map tools use it.
geo_text = (ROOT / 'src/functions/geomorphs.php').read_text()
geos = next(values for key, values in arrays(geo_text) if key == 'geomorphs')
geo_rows = []
for value in geos:
    parts = re.split('AAA|BBB|CCC|DDD|EEE|FFF', value)
    assert len(parts) == 7
    image, rooms, spot, more, delve, terrain, wayout = parts
    geo_rows.append(dict(image=image, rooms=[int(r) for r in rooms.split('_') if r.isdigit() and int(r)], spot=spot, more=more, delve=delve, terrain=terrain, wayout=int(wayout or 0)))
write('geomorphs', geo_rows)
from shutil import copyfile
(ROOT / 'js/maps').mkdir(exist_ok=True)
missing = []
for row in geo_rows:
    for prefix in ['', 'bw_'] if row['terrain'].startswith('scifi') else ['']:
        name = prefix + row['image']
        if (ROOT / 'src/maps' / name).exists():
            copyfile(ROOT / 'src/maps' / name, ROOT / 'js/maps' / name)
        elif prefix == '':
            missing.append(name)
assert not missing, missing
for name in ['worldmap', 'worldmap_legend']:
    source = json.loads((ROOT / 'data/json' / (name + '.json')).read_text())
    write(name, [dict(zip([c['name'] for c in source['columns']], row)) for row in source['rows']])
(ROOT / 'js/land').mkdir(exist_ok=True)
for path in (ROOT / 'src/land').glob('*.png'):
    copyfile(path, ROOT / 'js/land' / path.name)
# Preserve the outer title table and its literal alternatives with their indices.
parts = re.split(r'(?m)^\t\tcase ', titles_text.split('switch (mt_rand(0,108))')[1])[1:]
rows = {}
for part in parts:
    index = int(part.split(':', 1)[0])
    rows[index] = re.findall(r'\$title\s*=\s*"([^"$]*)"\s*;', part)
write('holmesTitles', {'rows': rows, 'places': re.findall(r'\$stitle\s*=\s*"([^"]+)"', titles_text), 'gearColors': next(v for k, v in arrays(titles_text) if k == 'gicolor')})
